class ShippingError extends Error {
  constructor(message) {
    super(message);
    this.name = this.constructor.name;
  }
}

class AddressError extends ShippingError {}
class WeightError extends ShippingError {}

function advice(error) {
  if (error instanceof AddressError) {
    return "check the address";
  }
  if (error instanceof ShippingError) {
    return "call the courier";
  }
  return "unknown problem";
}

console.log(advice(new WeightError("too heavy")));
console.log(advice(new AddressError("no street")));
console.log(advice(new Error("disk full")));
console.log(new WeightError("too heavy").name);
